## Quick Start

### 1. Check Wallet Availability

```typescript
if (typeof window.ethereum === 'undefined') {
  // Show "Install MetaMask" prompt
  throw new Error('MetaMask not installed');
}
```

### 2. Request Authorization

```typescript
const accounts = await window.ethereum.request({ method: 'eth_requestAccounts' });
// User sees approval popup in MetaMask
```

### 3. Get Account Address

```typescript
const address = accounts[0];
console.log('Address:', address);
```

### 4. Get Chain Information

```typescript
const chainId = await window.ethereum.request({ method: 'eth_chainId' });
// e.g., 0xa4b1 for Midnight testnet
```

## Common Patterns

### Connection State Hook

```typescript
function useMidnightWallet() {
  const [connected, setConnected] = useState(false);
  const [address, setAddress] = useState<string | null>(null);
  const [error, setError] = useState<Error | null>(null);

  const connect = async () => {
    try {
      if (!window.ethereum) throw new Error('MetaMask not installed');

      const accounts = await window.ethereum.request({ method: 'eth_requestAccounts' });
      if (accounts.length === 0) throw new Error('No accounts found');

      setAddress(accounts[0]);
      setConnected(true);
    } catch (e) {
      setError(e as Error);
    }
  };

  return { connected, address, error, connect };
}
```

### Display Address

```typescript
function formatAddress(address: string): string {
  // Standard hex address truncation
  if (address.length <= 20) return address;
  return `${address.slice(0, 6)}...${address.slice(-4)}`;
}
```

